final class Manager {
    var name: String
    var onUpdate: (() -> Void)?
    init(name: String) { self.name = name }
    func bind() {
        onUpdate = { [unowned self] in
            print("Update for \(self.name)")
        }
    }
    deinit { print("Manager \(name) freed") }
}

var m: Manager? = Manager(name: "Data")
m?.bind()
m?.onUpdate?()
m = nil
print("Manager scope exit")

final class Parent {
    var child: Child?
    deinit { print("Parent deinit") }
}

final class Child {
    weak var parent: Parent?
    deinit { print("Child deinit") }
}

var p: Parent? = Parent()
var c: Child? = Child()
p?.child = c
c?.parent = p
p = nil
print("Parent cleared")
c = nil
print("Child cleared")

final class CacheEntry {
    let key: String
    init(key: String) { self.key = key }
    deinit { print("Entry \(key) released") }
}

final class Store {
    var items: [CacheEntry] = []
    func add(_ entry: CacheEntry) { items.append(entry) }
    func purge() { items.removeAll() }
}

let store = Store()
store.add(CacheEntry(key: "A"))
store.add(CacheEntry(key: "B"))
print("Purging store")
store.purge()
print("Store empty")

final class Service {
    var callbacks: [() -> Void] = []
    var counter = 0
    func register() {
        callbacks.append {
            self.counter += 1
            print("Counter: \(self.counter)")
        }
    }
    deinit { print("Service deallocated") }
}

var s: Service? = Service()
s?.register()
s?.callbacks.first?()
s = nil
print("Completed")

